function App() {
  // BUG (illustrative): reads client-only storage during first render
  const initial = typeof window !== 'undefined'
    ? window.localStorage.getItem('theme')
    : 'light';
  const [theme] = useState(initial);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>Theme: {theme ?? 'light'} (mismatches: server says light, client may say dark)</p>
    </div>
  );
}

