function App() {
  // First render uses the SAME default the server used.
  const [theme, setTheme] = useState('light');
  useEffect(() => {
    // Read client-only storage AFTER hydration.
    const saved = window.localStorage.getItem('theme');
    if (saved) setTheme(saved);
  }, []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>Theme: {theme}</p>
      <small style={{ opacity: 0.6 }}>First render matches the server; localStorage applied after mount.</small>
    </div>
  );
}

