function App() {
  // Deterministic: stable keys and no random in render output.
  const items = ['Apples', 'Bananas', 'Cherries'];
  return (
    <ul style={{ fontFamily: 'system-ui', padding: 16 }}>
      {items.map((label, i) => (
        <li key={label}>{label} #{i + 1}</li>
      ))}
    </ul>
  );
}

'use client';
import { useState, useEffect } from 'react';

export default function Clock() {
  // First render matches the server: no time yet.
  const [time, setTime] = useState<string | null>(null);

  useEffect(() => {
    const update = () => setTime(new Date().toLocaleTimeString());
    update(); // client-only, after hydration
    const id = setInterval(update, 1000);
    return () => clearInterval(id);
  }, []);

  // Placeholder on first paint avoids the mismatch.
  return <span suppressHydrationWarning>{time ?? '--:--:--'}</span>;
}

